            // In wpSEO: noindex.
            3 => ['index' => 1, 'follow' => 0],
            // In wpSEO: noindex, follow.
            4 => ['index' => 1, 'follow' => 0],
            // In wpSEO: noindex, nofollow.
            5 => ['index' => 1, 'follow' => 1],
            // In wpSEO: index.
            6 => ['index' => 2, 'follow' => 0],
        ];
